import sys
import json
import os

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, 'usaspending_awards.json')
    awards_by_id = {}
    if os.path.exists(awards_path):
        with open(awards_path, 'r') as f:
            awards = json.load(f)
            for award in awards:
                award_id = award.get("generated_unique_award_id")
                if award_id:
                    if award_id not in awards_by_id:
                        awards_by_id[award_id] = []
                    awards_by_id[award_id].append(award)

    results = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity_id = pair.split("::", 1)
        fact_names = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact_name in fact_names:
            if entity_id not in awards_by_id:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_values = set()
            val_doc = None

            for award in awards_by_id[entity_id]:
                val = None
                if fact_name == "performance start":
                    pop = award.get("period_of_performance") or {}
                    val = pop.get("start_date")
                    if val is not None:
                        val = str(val)[:10]
                elif fact_name == "performance end":
                    pop = award.get("period_of_performance") or {}
                    val = pop.get("end_date")
                    if val is not None:
                        val = str(val)[:10]
                elif fact_name == "amount obligated":
                    val = award.get("total_obligation")
                    if val is not None:
                        val = str(val)
                elif fact_name == "potential value":
                    val = award.get("base_and_all_options")
                    if val is not None:
                        val = str(val)

                if val is not None:
                    extracted_values.add(val)
                    val_doc = [val, "usaspending_awards"]

            if len(extracted_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(extracted_values) == 1:
                pair_result[fact_name] = val_doc
            else:
                pair_result[fact_name] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

