import sys
import json
import os

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, 'usaspending_awards.json')
    awards_data = []
    if os.path.exists(awards_path):
        with open(awards_path, 'r') as f:
            awards_data = json.load(f)

    # Group records by generated_unique_award_id
    records_by_id = {}
    for record in awards_data:
        award_id = record.get("generated_unique_award_id")
        if award_id:
            records_by_id.setdefault(award_id, []).append(record)

    # Map fact names to their JSON paths
    fact_paths = {
        "performance start": ["period_of_performance", "start_date"],
        "performance end": ["period_of_performance", "end_date"],
        "amount obligated": ["total_obligation"],
        "potential value": ["base_and_all_options"]
    }

    results = {}

    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::")
        fact_names = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        records = records_by_id.get(entity, [])

        for fact in fact_names:
            path = fact_paths.get(fact)
            if not path:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for record in records:
                val = record
                for key in path:
                    if isinstance(val, dict) and key in val:
                        val = val[key]
                    else:
                        val = None
                        break

                if val is not None and val != "":
                    # Format dates as YYYY-MM-DD
                    if fact in ("performance start", "performance end"):
                        if isinstance(val, str) and len(val) >= 10:
                            val = val[:10]
                    # Format amounts as decimal strings
                    elif isinstance(val, (int, float)):
                        val = str(val)
                    else:
                        val = str(val)

                    values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], "usaspending_awards"]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

